(200318, 20032, 'single_choice', 'rubbish pit', '["A", "B", "C", "D", "E", "F", "G"]'::jsonb, 'A', 1, 18),
(200319, 20032, 'single_choice', 'meeting hall', '["A", "B", "C", "D", "E", "F", "G"]'::jsonb, 'G', 1, 19),
